CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','INACTIVE','SUSPENDED','DELETED');
CREATE TABLE "users" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"email" VARCHAR(320) NOT NULL,"password_hash" TEXT NOT NULL,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"email_verified" BOOLEAN NOT NULL DEFAULT false,"last_login_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE INDEX "users_status_idx" ON "users"("status");
CREATE TABLE "profiles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL,"first_name" VARCHAR(100) NOT NULL,"last_name" VARCHAR(100),"phone" VARCHAR(32),"profile_image_url" TEXT,"bio" TEXT,"city" VARCHAR(120),"state" VARCHAR(120),"country" VARCHAR(120),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "profiles_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "profiles_user_id_key" ON "profiles"("user_id");
CREATE TABLE "roles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" VARCHAR(80) NOT NULL,"description" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "roles_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "roles_name_key" ON "roles"("name");
CREATE TABLE "permissions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" VARCHAR(120) NOT NULL,"resource" VARCHAR(80) NOT NULL,"action" VARCHAR(40) NOT NULL,"description" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "permissions_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "permissions_name_key" ON "permissions"("name"); CREATE UNIQUE INDEX "permissions_resource_action_key" ON "permissions"("resource","action");
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL,"role_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "user_roles_pkey" PRIMARY KEY("user_id","role_id")); CREATE INDEX "user_roles_role_id_idx" ON "user_roles"("role_id");
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL,"permission_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "role_permissions_pkey" PRIMARY KEY("role_id","permission_id")); CREATE INDEX "role_permissions_permission_id_idx" ON "role_permissions"("permission_id");
CREATE TABLE "candidate_profiles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL,"headline" TEXT,"resume_url" TEXT,"experience_years" DECIMAL(5,2),"expected_salary" DECIMAL(14,2),"notice_period" VARCHAR(80),"preferred_location" TEXT,"github_url" TEXT,"linkedin_url" TEXT,"portfolio_url" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "candidate_profiles_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "candidate_profiles_user_id_key" ON "candidate_profiles"("user_id");
CREATE TABLE "skills" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" VARCHAR(120) NOT NULL,CONSTRAINT "skills_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "skills_name_key" ON "skills"("name");
CREATE TABLE "candidate_skills" ("candidate_id" UUID NOT NULL,"skill_id" UUID NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "candidate_skills_pkey" PRIMARY KEY("candidate_id","skill_id")); CREATE INDEX "candidate_skills_skill_id_idx" ON "candidate_skills"("skill_id");
CREATE TABLE "candidate_education" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"candidate_id" UUID NOT NULL,"institution" VARCHAR(200) NOT NULL,"degree" VARCHAR(160),"field_of_study" VARCHAR(160),"start_date" DATE,"end_date" DATE,"grade" VARCHAR(80),"description" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "candidate_education_pkey" PRIMARY KEY("id")); CREATE INDEX "candidate_education_candidate_id_idx" ON "candidate_education"("candidate_id");
CREATE TABLE "candidate_experience" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"candidate_id" UUID NOT NULL,"company_name" VARCHAR(200) NOT NULL,"job_title" VARCHAR(160) NOT NULL,"employment_type" VARCHAR(80),"start_date" DATE,"end_date" DATE,"is_current" BOOLEAN NOT NULL DEFAULT false,"description" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "candidate_experience_pkey" PRIMARY KEY("id")); CREATE INDEX "candidate_experience_candidate_id_idx" ON "candidate_experience"("candidate_id");
CREATE TABLE "resumes" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"candidate_id" UUID NOT NULL,"file_name" VARCHAR(255) NOT NULL,"file_url" TEXT NOT NULL,"storage_key" VARCHAR(500) NOT NULL,"mime_type" VARCHAR(120) NOT NULL,"file_size" BIGINT NOT NULL,"is_current" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "resumes_pkey" PRIMARY KEY("id")); CREATE INDEX "resumes_candidate_id_is_current_idx" ON "resumes"("candidate_id","is_current");
CREATE TABLE "companies" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" VARCHAR(200) NOT NULL,"website" TEXT,"logo_url" TEXT,"description" TEXT,"industry" VARCHAR(120),"company_size" VARCHAR(80),"city" VARCHAR(120),"state" VARCHAR(120),"country" VARCHAR(120),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "companies_pkey" PRIMARY KEY("id")); CREATE INDEX "companies_name_idx" ON "companies"("name");
CREATE TABLE "recruiter_profiles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"user_id" UUID NOT NULL,"company_id" UUID,"designation" VARCHAR(160),"department" VARCHAR(120),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "recruiter_profiles_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "recruiter_profiles_user_id_key" ON "recruiter_profiles"("user_id"); CREATE INDEX "recruiter_profiles_company_id_idx" ON "recruiter_profiles"("company_id");
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "user_roles" ADD CONSTRAINT "user_roles_role_id_fkey" FOREIGN KEY("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_role_id_fkey" FOREIGN KEY("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_permission_id_fkey" FOREIGN KEY("permission_id") REFERENCES "permissions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "candidate_profiles" ADD CONSTRAINT "candidate_profiles_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "candidate_skills" ADD CONSTRAINT "candidate_skills_candidate_id_fkey" FOREIGN KEY("candidate_id") REFERENCES "candidate_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "candidate_skills" ADD CONSTRAINT "candidate_skills_skill_id_fkey" FOREIGN KEY("skill_id") REFERENCES "skills"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "candidate_education" ADD CONSTRAINT "candidate_education_candidate_id_fkey" FOREIGN KEY("candidate_id") REFERENCES "candidate_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "candidate_experience" ADD CONSTRAINT "candidate_experience_candidate_id_fkey" FOREIGN KEY("candidate_id") REFERENCES "candidate_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "resumes" ADD CONSTRAINT "resumes_candidate_id_fkey" FOREIGN KEY("candidate_id") REFERENCES "candidate_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "recruiter_profiles" ADD CONSTRAINT "recruiter_profiles_user_id_fkey" FOREIGN KEY("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "recruiter_profiles" ADD CONSTRAINT "recruiter_profiles_company_id_fkey" FOREIGN KEY("company_id") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
